from dataclasses import dataclass, field
from enum import Enum
from typing import Dict, List, Any, Optional
import json
import hashlib
from datetime import datetime, timezone

class DecisionState(Enum):
    COMMITTED = "COMMITTED"
    DELIBERATION_REQUIRED = "DELIBERATION_REQUIRED"
    AUTHORIZATION_REQUIRED = "AUTHORIZATION_REQUIRED"
    REJECTED = "REJECTED"
    DEFERRED = "DEFERRED"

@dataclass
class InterpretationRecord:
    hemisphere_id: str
    intent: str
    semantic_payload: Dict[str, Any]
    assumptions: List[str]
    evidence_pointers: List[str]
    confidence: float
    alternatives_considered: List[str]
    timestamp: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

@dataclass
class CCDecisionResult:
    state: DecisionState
    action_payload: Optional[Dict[str, Any]]
    rationale: str
    disagreement_vector: Optional[Dict[str, Any]] = None
    required_tier: str = "free"
    audit_hash: str = ""

    def __post_init__(self):
        # Generate a cryptographic integrity hash for the decision record
        record_str = f"{self.state.value}:{str(self.action_payload)}:{self.rationale}:{self.timestamp if hasattr(self, 'timestamp') else ''}"
        self.audit_hash = hashlib.sha256(record_str.encode('utf-8')).hexdigest()

class ProtectedAppendOnlyLog:
    """Meets ADR-001 integrity requirements by preventing in-place mutations."""
    def __init__(self):
        self._log: List[Dict[str, Any]] = []

    def append(self, entry: Dict[str, Any]) -> str:
        # Enforce append-only immutability
        entry_copy = json.loads(json.dumps(entry))
        self._log.append(entry_copy)
        return entry['audit_hash']

class CorpusCallosumGovernor:
    def __init__(self, audit_log: ProtectedAppendOnlyLog):
        self.audit_log = audit_log

    def evaluate(self, proposal_a: InterpretationRecord, proposal_b: InterpretationRecord) -> CCDecisionResult:
        # Stage 1: Interpretation (Receive and preserve both proposals)
        # Maintained structurally via the inputs.

        # Stage 2: Deliberation (Analyze agreement, conflict, uncertainty)
        deliberation_result = self._deliberate(proposal_a, proposal_b)
        if deliberation_result.state != DecisionState.COMMITTED and deliberation_result.state != DecisionState.REJECTED:
            self.audit_log.append(self._to_log_entry(deliberation_result, proposal_a, proposal_b))
            return deliberation_result

        # Stage 3: Authorization (Check permissions, risk, reversibility, invariants)
        target_payload = deliberation_result.action_payload
        auth_result = self._authorize(target_payload)
        if auth_result.state != DecisionState.COMMITTED:
            self.audit_log.append(self._to_log_entry(auth_result, proposal_a, proposal_b))
            return auth_result

        # Stage 4: Execution (Commit through controlled channel)
        final_result = CCDecisionResult(
            state=DecisionState.COMMITTED,
            action_payload=target_payload,
            rationale="Hemispheric consensus verified, semantic schema validated, and authorization tier cleared.",
            required_tier=auth_result.required_tier
        )
        self.audit_log.append(self._to_log_entry(final_result, proposal_a, proposal_b))
        return final_result

    def _deliberate(self, a: InterpretationRecord, b: InterpretationRecord) -> CCDecisionResult:
        # Check semantic action equivalence rather than raw dict equality
        if a.semantic_payload.get("action_type") != b.semantic_payload.get("action_type"):
            return CCDecisionResult(
                state=DecisionState.DELIBERATION_REQUIRED,
                action_payload=None,
                rationale="Divergent action types proposed; preserving distinct interpretations for cross-examination.",
                disagreement_vector={"hemisphere_a": a.semantic_payload, "hemisphere_b": b.semantic_payload}
            )
        
        # If action types match, verify parameter compatibility
        if a.semantic_payload.get("parameters") != b.semantic_payload.get("parameters"):
            return CCDecisionResult(
                state=DecisionState.DELIBERATION_REQUIRED,
                action_payload=None,
                rationale="Parametric divergence detected under identical action type.",
                disagreement_vector={"hemisphere_a": a.semantic_payload, "hemisphere_b": b.semantic_payload}
            )

        # Agreement on payload: select the proposal with stronger evidential grounding
        chosen = a if len(a.evidence_pointers) >= len(b.evidence_pointers) else b
        return CCDecisionResult(
            state=DecisionState.COMMITTED,
            action_payload=chosen.semantic_payload,
            rationale="Semantically aligned payloads verified across both hemispheres."
        )

    def _authorize(self, payload: Dict[str, Any]) -> CCDecisionResult:
        action_class = payload.get("classification", "free")
        
        if action_class == "irreversible":
            return CCDecisionResult(
                state=DecisionState.AUTHORIZATION_REQUIRED,
                action_payload=payload,
                rationale="Action flagged as irreversible under ADR-001. Operator intervention required.",
                required_tier="gated_irreversible"
            )
        elif action_class == "integrity_critical":
            return CCDecisionResult(
                state=DecisionState.AUTHORIZATION_REQUIRED,
                action_payload=payload,
                rationale="Action modifies integrity-governed machinery or audit logs (ADR-001).",
                required_tier="gated_integrity"
            )

        return CCDecisionResult(
            state=DecisionState.COMMITTED,
            action_payload=payload,
            rationale="Action validated against Free Tier parameters.",
            required_tier="free"
        )

    def _to_log_entry(self, result: CCDecisionResult, a: InterpretationRecord, b: InterpretationRecord) -> Dict[str, Any]:
        return {
            "timestamp": datetime.now(timezone.utc).isoformat(),
            "state": result.state.value,
            "rationale": result.rationale,
            "audit_hash": result.audit_hash,
            "proposals": [
                {"hemisphere": a.hemisphere_id, "intent": a.intent, "confidence": a.confidence},
                {"hemisphere": b.hemisphere_id, "intent": b.intent, "confidence": b.confidence}
            ]
        }
